import boto3


def decrypt_payload(ciphertext, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    response = client.decrypt(CiphertextBlob=ciphertext["ciphertext"])
    return {"plaintext": response["Plaintext"].decode()}

import boto3


def envelope_encrypt(data, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    response = client.generate_data_key(KeyId=config["key_id"], KeySpec='AES_256')
    ciphertext_blob = response['CiphertextBlob']
    plaintext_key = response['Plaintext']
    encrypted_data = boto3.client('kms').encrypt(KeyId=config["key_id"], Plaintext=data['plaintext'])['CiphertextBlob']
    return {'ciphertext': ciphertext_blob, 'encrypted_data': encrypted_data}

import boto3


def sign_or_verify_key(message, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    response = client.sign(KeyId=config["key_id"], Message=message["message"], MessageType='RAW')
    return {'signature': response['Signature']}

